userscript.function:

const signModule = '<%=CommonUtil.getConfig("sepoa.sign.module", "nx")%>';
if(!$share.toolkit) {
    $share.toolkit = {};
}

const docInfo = getContractData(Sepoa.params.CONT_NO, Sepoa.params.CONT_GL_SEQ);
if(docInfo === false) {
    return false;
}

sUtils.object.extend(true, $share, docInfo);

let target;
switch(signModule) {
    case 'one' : {
        target = $share.toolkit.one = new SepoaCertSign({
            module: 'certModuleOne',
            methodOrder : ['samsung-pass', 'pass', 'kakao', 'naver']
        });
        $share.toolkit.one.attachEvent('onModuleReady', (secukit) => {
            doClientSign(Sepoa.params.CONT_NO, Sepoa.params.CONT_GL_SEQ, 'ONE');
        });
        $share.toolkit.one.attachEvent('onSignPass', (data) => {
            const params = sUtils.object.extend(true, {}, 
                data,
                Sepoa.params
            );

            const targetInfo = $share.SIGNER.find(e => e.SIGNER_ID == Sepoa.info.ID);
            if(targetInfo) {
                params.TARGET = targetInfo;
            }

            doSignEnd(params);
        });

        break;
    }
    case 'nx' : 
    default :
        Alert('not supported module : ' + signModule);
        break;
}

if(target) {
    Confirm('계약서를 확인하기 위해서는 본인인증이 필요합니다.<br>본인인증을 진행하시겠습니까?', (flag) => {
        if(flag) {
            target.init();
        }
    })
}


if(sUtils.string.isBlank(contNo,) && sUtils.string.isBlank(contGlSeq)) {
    return false;
}

const config = {
    url : window.CONTEXT_NAME+'/SepoaActionController.sux',
    async : false,
    contentType : 'json'
};

const params = {
    module : 'contract',
    action : 'doDocumentDetail',
    CONNECTION : 'CONNECTION',
    CONT_NO: contNo,
    CONT_GL_SEQ: contGlSeq
};

const so = sUtils.multipart.send(config, params);
if(so.flag === false) {
    Alert(so.message);
    return false;
}

return so.result[0];


const config = {
    url : window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback : function(res, config, params) {
            if(res.status == 1){
                $share.toolkit[config._SIGN_TYPE.toLowerCase()].doSign({
                    SIGN_ORG_VALUE : res.result[0].SIGN_HASH,
                    SIGN_KEY : res.result[0].SIGN_KEY
                });
            } else {
                Alert(res.message);
            }
        }
    },
    _SIGN_TYPE : signModule
}

const params = {
    module : 'contract',
    action : 'doSelectClientSignInfo',
    CONNECTION : 'CONNECTION',
    CONT_NO : contNo,
    CONT_GL_SEQ : contGlSeq,
    CHECK_CURRENT_SIGNER : false
}

sUtils.multipart.send(config, params);


const config = {
    url : window.CONTEXT_NAME + '/SepoaSignOne.sux?type=verify',
    contentType : 'json',
    on : {
        callback : (res) => {
            if(res.flag) {
                const addHidden = function(form, name, value) {
                    const input = document.createElement('input');
                    input.type = 'hidden';
                    input.name = name;
                    input.value = value;
                    form.insertBefore(input, null);
                }

                const form = document.body.appendChild($('<form target="sepoa-link-frame" style="display:none"></form>')[0]);
                const target = res;
                if(target) {
                    target['parameterId'] = 'LINK_' + new Date().getTime();
                    target['isPopup'] = true;
                    target['onLink'] = true;
                    target['isRealPopup'] = true;
                }

                for(let entry of Object.entries(target)) {
                    const [key, value] = entry;
                    addHidden(form, key, value);
                }

                if(!SUX.root.modalPopupInfo){
                    SUX.root.modalPopupInfo = {};
                }
                SUX.root.modalPopupInfo[target['parameterId']] = {
                    params: target
                };

                form.target = window.name;
                form.action = window.CONTEXT_NAME + '/Contract/Module/ContractModuleLayout.sux';
                form.method = 'post';
                form.submit();
            } else {
                Alert(res.message);
            }
        }
    }
};

const params = sUtils.object.extend(true, {}, data);

sUtils.multipart.send(config, params);
